export class CombatEffects {
  constructor(portrait){this.portrait=portrait;this.timers=new Set();this.enabled=!matchMedia('(prefers-reduced-motion: reduce)').matches;this.sound=false;this.lastCutin=-Infinity;this.ctx=null;}
  later(fn,ms){const id=setTimeout(()=>{this.timers.delete(id);fn();},ms);this.timers.add(id);return id;}
  clear(){for(const id of this.timers)clearTimeout(id);this.timers.clear();for(const id of ['fx','cutin','combatBanner','comboMeter']){const el=document.getElementById(id);el.replaceChildren();el.classList.remove('show');}document.querySelector('.arena').classList.remove('shake','finisher');this.lastCutin=-Infinity;}
  animate(el,cls,ms){if(!el)return;el.classList.remove(cls);void el.offsetWidth;el.classList.add(cls);this.later(()=>el.classList.remove(cls),ms);}
  tone(kind='hit'){if(!this.sound)return;try{this.ctx??=new AudioContext();this.ctx.resume();const now=this.ctx.currentTime;const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.connect(g);g.connect(this.ctx.destination);o.type=kind==='ult'?'sawtooth':'triangle';o.frequency.setValueAtTime(kind==='ult'?130:kind==='heal'?640:330,now);o.frequency.exponentialRampToValueAtTime(kind==='ult'?35:kind==='heal'?880:90,now+.15);g.gain.setValueAtTime(kind==='ult'?.05:.025,now);g.gain.exponentialRampToValueAtTime(.001,now+.2);o.start();o.stop(now+.21);}catch{}}
  banner(title,sub){const el=document.getElementById('combatBanner');el.innerHTML=`<strong>${title}</strong><small>${sub}</small>`;this.animate(el,'show',1150);}
  cutin(hero,label){if(!this.enabled||performance.now()-this.lastCutin<1700)return false;this.lastCutin=performance.now();const el=document.getElementById('cutin');el.style.setProperty('--cutin-color',hero.color);el.innerHTML=this.portrait(hero.id,'cutin-portrait')+`<div class="cutin-copy"><small>RESONANCE LIBERATION</small><strong>${label}</strong><span>${hero.name} · 공명 해방</span></div>`;this.animate(el,'show',950);this.tone('ult');return true;}
  hit(event,color){const from=document.querySelector(`[data-uid="${event.from}"]`),to=document.querySelector(`[data-uid="${event.to}"]`);if(!to)return;const pop=document.createElement('span');pop.className=`damage ${event.kind}`;pop.textContent=`${event.kind==='heal'?'+':event.kind==='coop'?'협동 ':event.kind==='extra'?'추격 ':''}${event.amount}`;to.append(pop);this.later(()=>pop.remove(),700);if(event.kind==='heal'){this.tone('heal');return;}this.tone(event.kind==='ult'?'ult':'hit');this.animate(to,'hit',230);this.animate(from,'attacking',280);if(!this.enabled||!from)return;const arena=document.querySelector('.arena'),r=arena.getBoundingClientRect(),a=from.getBoundingClientRect(),b=to.getBoundingClientRect();const x=a.left+a.width/2-r.left,y=a.top+a.height/2-r.top,tx=b.left+b.width/2-r.left,ty=b.top+b.height/2-r.top;const fx=document.getElementById('fx');const line=document.createElement('i');line.className=`beam ${event.kind}`;line.style.cssText=`left:${x}px;top:${y}px;width:${Math.hypot(tx-x,ty-y)}px;transform:rotate(${Math.atan2(ty-y,tx-x)}rad);--beam-color:${color}`;fx.append(line);this.later(()=>line.remove(),320);const ring=document.createElement('i');ring.className='burst';ring.style.cssText=`left:${tx}px;top:${ty}px;--impact:${color}`;fx.append(ring);this.later(()=>ring.remove(),400);if(event.kind==='ult'||event.kill){this.animate(arena,'shake',230);for(let i=0;i<7;i++){const angle=i*Math.PI*2/7,spark=document.createElement('i');spark.className='spark';spark.style.cssText=`left:${tx}px;top:${ty}px;--impact:${color};--angle:${angle}rad;--dx:${Math.cos(angle)*45}px;--dy:${Math.sin(angle)*45}px`;fx.append(spark);this.later(()=>spark.remove(),410);}}}
  combo(n){const el=document.getElementById('comboMeter');el.innerHTML=`${n} CHAIN<small>공명 연쇄</small>`;this.animate(el,'show',950);}
}
